INSERT INTO catalog.skill (slug, kind) VALUES ('agent-network-single-node', 'context') ON CONFLICT DO NOTHING;
INSERT INTO catalog.skill_version (skill_slug, version_id, repository_url, git_commit, source_directory, routing_description, importer_version) VALUES ('agent-network-single-node', '598ea801e8dab5722ac9e991517abcff191ba8a3e9bf3c03e32c07ff1216833b', 'https://github.com/getcolors/skills', '3c82f5c9fc1400f748988e8295ab3af7cf5994d5', 'agent-network-single-node', 'Everything a single-node NetBird Agent Network deployment needs that the docs and the quickstart installer will not tell you - the four-container gateway stack plus one network-isolated agent, the endpoint that is minted by POSTing the settings resource and not by connecting a provider, the reverse proxy whose per-name ACME is defective on 0.77.1 ("no viable challenge type found") and burns Let''s Encrypt rate limits while failing, and the acceptance gates that prove an isolation claim instead of assuming it. Use this whenever the user mentions NetBird Agent Network, a keyless or identity-gated LLM endpoint, the netbird reverse proxy, or an AI agent that must not reach the internet - even if they do not say "single-node". Also use it on these symptoms - an endpoint hostname with HTTP 000 or no certificate, 422 "is not a known catalog provider", llm_policy.model_blocked or model_not_routable, or an isolated container escaping after a Docker restart. The full symptom index is at the top of the body.', '2') ON CONFLICT DO NOTHING;
