INSERT INTO catalog.skill_version (skill_slug, version_id, repository_url, git_commit, source_directory, routing_description, importer_version) VALUES ('automq-multi-node', 'c672ce61d4cb64c46e8c1f14148a9def17605719ee1b665e0e2d96ee24f85808', 'https://github.com/getcolors/skills', '3c82f5c9fc1400f748988e8295ab3af7cf5994d5', 'automq-multi-node', 'Diagnose multi-node AutoMQ deployments backed by object storage. Use for KRaft stuck in CandidateState or waiting for the high water mark, SCRAM-SHA-512 invalid credentials for every principal, missing KafkaServer JAAS entries, gates that pass only once, and bucket or SSH key ownership failures. Carries verified Vultr, AWS, Google Cloud and OCI context, including conditional-write, identity and VM allocation failures, listener and genesis contracts, and targeted failover acceptance gates.', '2') ON CONFLICT DO NOTHING;
