INSERT INTO catalog.skill_version (skill_slug, version_id, repository_url, git_commit, source_directory, routing_description, importer_version) VALUES ('langfuse-multi-node', 'da32c1e8c71ae1759d2cb5466e630da466e187381c001448dd299a08487f62bb', 'https://github.com/getcolors/skills', '3c82f5c9fc1400f748988e8295ab3af7cf5994d5', 'langfuse-multi-node', 'Everything a self-hosted Langfuse v4 on separate machines needs that the docs and the Compose quick start will not tell you - langfuse-web restart-looping on ''P3005 The database schema is not empty'' against a brand-new Neon database, traces that never appear after a 207 from /api/public/ingestion (''Rejected N event(s) from the legacy /api/public/ingestion endpoint ... events_only mode''), GET /api/public/traces/<id> answering 404 while health is green, an empty traces table on a healthy ClickHouse, POST /api/public/media answering 201, ClickHouse failing to start with ''SAXParseException Invalid token'' or ''PARTITION BY parameters should be specified directly inside engine'', a BACKUP_CREATED that leaves randomly named objects in R2, ''Not enough privileges ... SHOW COLUMNS ON system.one'', and SHOW timezone returning GMT. Use whenever the user runs Langfuse v4 on more than one host, puts its Postgres on Neon, or backs ClickHouse up to S3-compatible storage. Full symptom index at the top of the body.', '2') ON CONFLICT DO NOTHING;
