INSERT INTO catalog.section (skill_slug, version_id, path, ordinal, kind, heading, heading_path, start_line, end_line, body) VALUES ('langfuse-multi-node', 'da32c1e8c71ae1759d2cb5466e630da466e187381c001448dd299a08487f62bb', 'references/pins.md', 2, 'pins', 'The rules that generated it', ARRAY['Pins','The rules that generated it']::text[], 23, 24, '## The rules that generated it

