INSERT INTO catalog.eval_case (skill_slug, version_id, path, ordinal, source_id, name, prompt, expected_output, assertions, raw_case) VALUES ('neon-multi-node', '3b5e82f1c9a4e6007d69caa5bff43bced7719d566f03e1c3e7ffbf955cc080d9', 'evals/evals.json', 0, '0', 'ssl-off', 'My five-machine Neon deployment has an Active pageserver and compute is running, but psql says "server does not support SSL, but SSL was required". The spec already has compute_ctl_config.tls and the certificate files exist. Should I restart until it notices them?', 'Identify pinned compute.rs::tls_config experimental feature gate; Explain enabling tls_experimental alone is not the final verified fix; Route to native PostgreSQL SSL settings and external verify-full plus plaintext rejection.', '["Identify pinned compute.rs::tls_config experimental feature gate", "Explain enabling tls_experimental alone is not the final verified fix", "Route to native PostgreSQL SSL settings and external verify-full plus plaintext rejection"]', '{"id": 0, "name": "ssl-off", "prompt": "My five-machine Neon deployment has an Active pageserver and compute is running, but psql says \"server does not support SSL, but SSL was required\". The spec already has compute_ctl_config.tls and the certificate files exist. Should I restart until it notices them?", "expected_output": "Identify pinned compute.rs::tls_config experimental feature gate; Explain enabling tls_experimental alone is not the final verified fix; Route to native PostgreSQL SSL settings and external verify-full plus plaintext rejection.", "files": [], "assertions": ["Identify pinned compute.rs::tls_config experimental feature gate", "Explain enabling tls_experimental alone is not the final verified fix", "Route to native PostgreSQL SSL settings and external verify-full plus plaintext rejection"]}') ON CONFLICT DO NOTHING;
