INSERT INTO catalog.pin_row (skill_slug, version_id, path, section_ordinal, line_number, component, value_text, cells) VALUES ('neon-single-node', '7aa2034b2b3aa012feb01c55278f7d03f1af6856045758aec01b14ef5a0f4066', 'references/pins.md', 1, 14, 'host packages', 'Ubuntu 24.04 apt: `docker.io`, `docker-compose-v2`, `postgresql-client`, `rclone` (v1.60.1-DEV — the rclone flags below exist because of this vintage), `jq`, `openssl`, `python3`', '["host packages", "Ubuntu 24.04 apt: `docker.io`, `docker-compose-v2`, `postgresql-client`, `rclone` (v1.60.1-DEV — the rclone flags below exist because of this vintage), `jq`, `openssl`, `python3`"]') ON CONFLICT DO NOTHING;
