INSERT INTO catalog.skill_version (skill_slug, version_id, repository_url, git_commit, source_directory, routing_description, importer_version) VALUES ('posthog-single-node', 'fbc57a791e955757d0d879006695cc264b23ad16435535826178bad3653a0832', 'https://github.com/getcolors/skills', '3c82f5c9fc1400f748988e8295ab3af7cf5994d5', 'posthog-single-node', 'Everything needed to stand up a working self-hosted single-node PostHog on one server - the ten-container topology, the ClickHouse Keeper/macros/named-collections configuration PostHog''s migrations require, the capture and plugin-server ingestion chain, the converge ordering, and a catalogue of ~30 failures that each look like success. Use this whenever the user mentions self-hosting, deploying, provisioning, upgrading, or debugging PostHog, or is working on a PostHog docker-compose, Ansible playbook, ClickHouse schema, migrate_clickhouse run, or event-ingestion problem - even if they do not say "single-node" and even if they think their problem is small. Also use it when someone reports that PostHog accepts events but stores none, that a container "runs" but serves nothing, or that Celery will not start.', '2') ON CONFLICT DO NOTHING;
